import { NextRequest } from 'next/server';

interface Post {
  id: number;
  title: string;
  content: string;
  createdAt: string;
}

interface UpdatedPost {
  id: number;
  title: string;
  content: string;
  updatedAt: string;
}

interface PutBody {
  title?: string;
  content?: string;
}

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(
  _request: NextRequest,
  { params }: RouteContext,
): Promise<Response> {
  const { id } = await params;

  const post: Post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return Response.json(post);
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext,
): Promise<Response> {
  const { id } = await params;
  const body: PutBody = await request.json();
  const { title, content } = body;

  const updatedPost: UpdatedPost = {
    id: parseInt(id),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return Response.json(updatedPost);
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext,
): Promise<Response> {
  const { id } = await params;

  return Response.json({ message: `Post ${id} deleted successfully` });
}

